export interface ConnectorConfig {
  /** Airtable personal access token or OAuth token. Env: AIRTABLE_API_KEY */
  airtableApiKey: string;
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX). */
  airtableBaseId: string;
  /** Airtable table ID or name (e.g., tblXXXXXXXXXXXXXX or "Orders"). */
  airtableTableIdOrName: string;
  /** Optional fetch implementation for testing. */
  fetch?: typeof fetch;
}

export interface ShopifyOrderPaidPayload {
  id: string;
  totals: Array<{ type: string; amount: number }>;
  email?: string;
  // Other properties (ucp, label, currency, line_items, fulfillment) are ignored.
}

export interface HandleResult {
  recordIds: string[];
}

function extractOrderId(shopifyId: string): string {
  const parts = shopifyId.split('/');
  return parts[parts.length - 1];
}

function extractTotalPrice(totals: Array<{ type: string; amount: number }>): string {
  const total = totals.find((t) => t.type === 'total');
  if (!total) {
    throw new Error('Missing total amount in payload totals');
  }
  // Amount is in cents; convert to dollars with two decimal places.
  return (total.amount / 100).toFixed(2);
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.id) {
    throw new Error('Missing required field: id');
  }
  if (!payload.totals || !Array.isArray(payload.totals)) {
    throw new Error('Missing required field: totals');
  }

  const orderId = extractOrderId(payload.id);
  const totalPrice = extractTotalPrice(payload.totals);
  const customerEmail = payload.email ?? '';

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableIdOrName}`;
  const body = {
    records: [
      {
        fields: {
          'Order ID': orderId,
          'Customer Email': customerEmail,
          Total: totalPrice,
        },
      },
    ],
  };

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at ${url}`);
  }

  const data = (await response.json()) as { records: Array<{ id: string }> };
  const recordIds = data.records.map((r) => r.id);
  return { recordIds };
}

