describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    airtableApiKey: 'test-key',
    airtableBaseId: 'appTestBase',
    airtableTableIdOrName: 'tblTestTable',
  };

  it('happy path: creates record with correct field mapping and auth', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.airtable.com/v0/appTestBase/tblTestTable' &&
      req.method === 'POST'
        ? jsonResponse({
            records: [{ id: 'rec123', createdTime: '2023-01-01T00:00:00.000Z', fields: {} }],
          })
        : jsonResponse({ error: 'not found' }, 404)
    );

    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/1234567890',
      totals: [
        { type: 'subtotal', amount: 1000 },
        { type: 'total', amount: 1234 },
      ],
      email: 'customer@example.com',
    };

    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.recordIds).toEqual(['rec123']);

    expect(calls).toHaveLength(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://api.airtable.com/v0/appTestBase/tblTestTable');
    expect(call.headers.get('authorization')).toBe('Bearer test-key');
    expect(call.json).toEqual({
      records: [
        {
          fields: {
            'Order ID': '1234567890',
            'Customer Email': 'customer@example.com',
            Total: '12.34',
          },
        },
      ],
    });
  });

  it('uses empty string for email when not provided', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ records: [{ id: 'rec456' }] })
    );

    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/999',
      totals: [{ type: 'total', amount: 5000 }],
    };

    await handle(payload, { ...baseConfig, fetch });
    expect(calls[0].json).toEqual({
      records: [
        {
          fields: {
            'Order ID': '999',
            'Customer Email': '',
            Total: '50.00',
          },
        },
      ],
    });
  });

  it('throws descriptive error when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { totals: [{ type: 'total', amount: 100 }] } as unknown as ShopifyOrderPaidPayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: id');
  });

  it('throws descriptive error when totals is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { id: 'gid://shopify/Order/1' } as unknown as ShopifyOrderPaidPayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: totals');
  });

  it('throws descriptive error when total type is not found in totals', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/1',
      totals: [{ type: 'subtotal', amount: 100 }],
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing total amount in payload totals');
  });

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Invalid field' }, 422));
    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/1',
      totals: [{ type: 'total', amount: 100 }],
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Airtable API error: 422 Unprocessable Entity at https://api.airtable.com/v0/appTestBase/tblTestTable'
    );
  });
});

